import React, { useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { FiMapPin, FiPhone, FiUser, FiX, FiEye } from 'react-icons/fi';

const ProductModal = ({ product, isOpen, onClose }) => {
    const { user } = useAuth();
    const [showContact, setShowContact] = React.useState(false);
    const [currentPhotoIndex, setCurrentPhotoIndex] = React.useState(0);

    // Fechar ao pressionar ESC
    useEffect(() => {
        const handleEsc = (e) => {
            if (e.key === 'Escape') onClose();
        };
        window.addEventListener('keydown', handleEsc);
        return () => window.removeEventListener('keydown', handleEsc);
    }, [onClose]);

    // Fechar ao clicar fora do modal
    const handleBackdropClick = (e) => {
        if (e.target === e.currentTarget) onClose();
    };

    // Impedir scroll do body quando modal está aberto
    useEffect(() => {
        if (isOpen) {
            document.body.style.overflow = 'hidden';
        } else {
            document.body.style.overflow = 'unset';
        }
        return () => {
            document.body.style.overflow = 'unset';
        };
    }, [isOpen]);

    if (!isOpen || !product) return null;

    const getCategoryIcon = (category) => {
        const icons = { telemovel: '📱', laptop: '💻', console: '🎮', tablet: '📟' };
        return icons[category] || '📦';
    };

    const getContactMethodIcon = (method) => {
        if (method === 'whatsapp') return '💚 WhatsApp';
        if (method === 'call') return '📞 Ligação';
        return '💚 WhatsApp / 📞 Ligação';
    };

    const handleContact = () => {
        if (!user) {
            alert('Faça login para ver o contato');
            return;
        }
        setShowContact(true);
    };

    const isOwner = user && product.sellerId === user.id;

    return (
        <div 
            className="fixed inset-0 bg-black bg-opacity-50 backdrop-blur-sm flex items-center justify-center z-50 p-4"
            onClick={handleBackdropClick}
        >
            <div className="bg-white rounded-2xl max-w-2xl w-full max-h-[90vh] overflow-y-auto shadow-2xl">
                {/* Cabeçalho com botão fechar */}
                <div className="sticky top-0 bg-white border-b p-4 flex justify-between items-center">
                    <h2 className="text-xl font-bold text-gray-800">Detalhes do Produto</h2>
                    <button 
                        onClick={onClose}
                        className="p-2 hover:bg-gray-100 rounded-full transition"
                    >
                        <FiX size={20} />
                    </button>
                </div>

                {/* Conteúdo do Modal */}
                <div className="p-6">
                    {/* Imagem Principal */}
                    <div className="bg-gray-100 rounded-xl p-4 flex justify-center items-center mb-4 min-h-[250px]">
                        {product.photos && product.photos.length > 0 ? (
                            <img 
                                src={`http://localhost:3001${product.photos[currentPhotoIndex]}`} 
                                alt={product.title} 
                                className="max-w-full max-h-[200px] object-contain" 
                            />
                        ) : (
                            <div className="text-6xl text-gray-400">
                                {getCategoryIcon(product.category)}
                            </div>
                        )}
                    </div>

                    {/* Miniaturas */}
                    {product.photos && product.photos.length > 1 && (
                        <div className="flex gap-2 mb-6 overflow-x-auto pb-2">
                            {product.photos.map((photo, idx) => (
                                <button
                                    key={idx}
                                    onClick={() => setCurrentPhotoIndex(idx)}
                                    className={`w-16 h-16 rounded-lg overflow-hidden border-2 flex-shrink-0 ${
                                        currentPhotoIndex === idx ? 'border-primary-600' : 'border-gray-200'
                                    }`}
                                >
                                    <img 
                                        src={`http://localhost:3001${photo}`} 
                                        alt={`Foto ${idx + 1}`} 
                                        className="w-full h-full object-cover" 
                                    />
                                </button>
                            ))}
                        </div>
                    )}

                    {/* Título e Estado */}
                    <div className="flex items-start justify-between mb-2">
                        <h3 className="text-xl font-bold text-gray-800">{product.title}</h3>
                        <span className={`px-2 py-1 rounded-full text-xs font-semibold ${
                            product.condition === 'novo' ? 'bg-green-100 text-green-600' : 'bg-yellow-100 text-yellow-600'
                        }`}>
                            {product.condition === 'novo' ? 'Novo' : 'Semi-novo'}
                        </span>
                    </div>

                    {/* Categoria */}
                    <p className="text-sm text-gray-500 mb-2">{product.category}</p>

                    {/* Preço */}
                    <p className="text-2xl font-bold text-primary-600 mb-4">
                        {product.price.toLocaleString()} Kz
                    </p>

                    {/* Descrição */}
                    <div className="border-t border-gray-100 pt-4 mb-4">
                        <p className="text-gray-700 leading-relaxed whitespace-pre-line">{product.description}</p>
                    </div>

                    {/* Informações adicionais */}
                    <div className="space-y-2 mb-6 text-sm">
                        <div className="flex items-center text-gray-500">
                            <FiMapPin className="mr-2 text-gray-400" size={14} />
                            <span>{product.location}</span>
                        </div>
                        <div className="flex items-center text-gray-500">
                            <FiUser className="mr-2 text-gray-400" size={14} />
                            <span>Vendedor: {product.sellerName}</span>
                        </div>
                        <div className="flex items-center text-gray-400">
                            <FiEye className="mr-2" size={14} />
                            <span>{product.views || 0} visualizações</span>
                        </div>
                    </div>

                    {/* Área de Contato */}
                    {!isOwner && (
                        <div className="mt-4">
                            {showContact ? (
                                <div className="bg-green-50 rounded-xl p-4 border border-green-200">
                                    <div className="flex items-center gap-2 text-green-600 mb-2">
                                        <FiPhone className="text-green-500" />
                                        <span className="font-medium">{getContactMethodIcon(product.contactMethod)}</span>
                                    </div>
                                    <p className="text-lg font-bold text-green-700 mb-1">{product.contactNumber}</p>
                                    {product.contactHours && (
                                        <p className="text-sm text-green-600">Horário: {product.contactHours}</p>
                                    )}
                                </div>
                            ) : (
                                <button
                                    onClick={handleContact}
                                    className="w-full bg-primary-600 text-white py-2 rounded-lg font-medium hover:bg-primary-700 transition"
                                >
                                    Ver número do vendedor
                                </button>
                            )}
                        </div>
                    )}

                    {isOwner && (
                        <div className="bg-blue-50 rounded-xl p-4 border border-blue-200 mt-4">
                            <p className="text-blue-600 font-medium">📌 Este é seu anúncio</p>
                            <p className="text-sm text-blue-600 mt-1">
                                <strong>Contato:</strong> {getContactMethodIcon(product.contactMethod)}<br />
                                <strong>Número:</strong> {product.contactNumber}
                            </p>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default ProductModal;
